mapper.select:
SELECT #{tenantId} AS tenant_id,

           #{modelName}
           NULL
        AS model_name,
       COUNT(*) AS request_count,
       COALESCE(SUM(total_tokens), 0) AS total_tokens
FROM api_usage_log


      USE INDEX (idx_tenant_model_time_tokens)


      USE INDEX (idx_tenant_time_tokens)


WHERE tenant_id = #{tenantId}

    AND model_name = #{modelName}


    AND create_time >= #{startTime}


    AND create_time <= #{endTime}

SELECT id, request_id, tenant_id, model_name, provider, channel_id,
       prompt_tokens, completion_tokens, total_tokens, cost_ms, finish_reason, estimated, create_time
FROM api_usage_log


      USE INDEX (idx_tenant_model_time)


      USE INDEX (idx_tenant_create_time)


WHERE tenant_id = #{tenantId}

    AND model_name = #{modelName}


    AND create_time <= #{lastCreateTime}
    AND (create_time, id) < (#{lastCreateTime}, #{lastId})

ORDER BY create_time DESC, id DESC
LIMIT #{pageSize}

SELECT id, request_id, tenant_id, model_name, provider, channel_id,
       prompt_tokens, completion_tokens, total_tokens, cost_ms, finish_reason, estimated, create_time
FROM api_usage_log


      USE INDEX (idx_tenant_model_time)


      USE INDEX (idx_tenant_create_time)


WHERE tenant_id = #{tenantId}

    AND model_name = #{modelName}

ORDER BY create_time DESC, id DESC
LIMIT #{offset}, #{pageSize}

SELECT COUNT(*)
FROM api_usage_log
WHERE tenant_id = #{tenantId}
